<script setup lang="ts">
import { uiText } from '@/i18n'

import { ref,watch,onBeforeUnmount } from 'vue'
import { request } from '@/api/client'
import { wordSpeaker } from '@/lib/pronunciation'
import { authStore } from '@/stores/auth'
const props=defineProps<{kind:'NOTE'|'DOCUMENT';sourceId:string;disabled?:boolean}>()
const host=ref<HTMLElement>(),quote=ref(''),term=ref(''),message=ref(''),busy=ref(false),definition=ref<{ipa:string;meaning:string;example:string;usageNote:string}>(),speaker=wordSpeaker()
let id=crypto.randomUUID(),epoch=0,alive=true
function selection(){if(props.disabled||busy.value)return;const s=window.getSelection();if(!s?.rangeCount||!host.value?.contains(s.anchorNode)||!host.value.contains(s.focusNode))return;const value=s.toString().trim();if(!value||value.length>4000)return;quote.value=value;term.value=/^[a-zA-Z][a-zA-Z '\-]{0,79}$/.test(value)?value:'';message.value='';definition.value=undefined;id=crypto.randomUUID();epoch++}
async function lookup(){if(!term.value.trim()||busy.value)return;const version=epoch;busy.value=true;message.value='';try{const result=await request<typeof definition.value>('/vocabulary/lookup?term='+encodeURIComponent(term.value.trim()));if(alive&&version===epoch)definition.value=result}catch(e){if(alive&&version===epoch)message.value=(e as Error).message}finally{if(alive)busy.value=false}}
async function capture(action:string){if(busy.value)return;const version=epoch;busy.value=true;message.value='';try{await request('/learning/clips',{method:'POST',body:JSON.stringify({kind:props.kind,sourceId:props.sourceId,quote:quote.value,term:term.value||null,action,requestId:id})});if(alive&&version===epoch){message.value=action==='WORD'?'已收藏单词，并保留原句与来源':action==='CARD'?'已保存复习卡，可在学习中心编辑问题':'已保存阅读笔记';id=crypto.randomUUID()}}catch(e){if(alive&&version===epoch)message.value=(e as Error).message}finally{if(alive)busy.value=false}}
function clear(){epoch++;quote.value='';definition.value=undefined;message.value='';speaker.stop()}
watch(()=>[props.sourceId,props.disabled],clear);onBeforeUnmount(()=>{alive=false;clear()})
</script>
<template><div><div ref="host" @mouseup="selection" @keyup="selection"><slot/></div><section v-if="quote" class="reading-selection" :aria-label="uiText('选区学习')"><div class="selection-heading"><strong>{{ uiText('留下这一段') }}</strong><button class="table-action" :disabled="busy" @click="clear">{{ uiText('收起') }}</button></div><blockquote>{{quote}}</blockquote><div class="selection-tools"><template v-if="authStore.has('vocabulary:use')"><input v-model="term" class="field-input" maxlength="80" :aria-label="uiText('选区中的单词')" :placeholder="uiText('原句中的单词或短语')" :disabled="busy"/><button class="button" :disabled="busy||!term.trim()" @click="lookup">{{ uiText('查词') }}</button><button class="button" :disabled="!term.trim()" @click="speaker.say(term)">{{ uiText('听读') }}</button><button class="button" :disabled="busy||!term.trim()" @click="capture('WORD')">{{ uiText('加入单词本') }}</button></template><button v-if="authStore.has('research:use')" class="button" :disabled="busy" @click="capture('CARD')">{{ uiText('制作复习卡') }}</button><button v-if="authStore.has('note:write')" class="button" :disabled="busy" @click="capture('NOTE')">{{ uiText('保存摘录') }}</button></div><p v-if="definition"><strong>{{definition.ipa}} · {{definition.meaning}}</strong><br/>{{definition.example}}<br/>{{definition.usageNote}}</p><p v-if="message" role="status">{{message}}</p></section></div></template>
<style scoped>.reading-selection{margin:20px 0;padding:22px;border:1px solid var(--line);border-radius:12px;background:var(--surface-soft)}.selection-heading,.selection-tools{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.selection-heading{justify-content:space-between}.selection-tools input{width:210px}.reading-selection blockquote{margin:16px 0;padding-left:14px;border-left:2px solid var(--green);max-height:120px;overflow:auto;white-space:pre-wrap}.reading-selection p{font-size:14px;line-height:1.8}</style>
